// Get data from both sheets
const gaItems = $input.first().json;
const msItems = $input.last().json;

// Define the list names to check
const targetListNames = [
  'bad tech',
  'PC, invest, sensitive content, sites, logins, misc',
  'skill-seekers, deals, errors',
  'too short',
  'competitors',
  'too short - sql perf',
  'SQL Deployments',
  'Irrelevant info queries'
];

// Helper function to create a unique key for keyword comparison
// Important: Match type matters - "sql server" and [sql server] are different
function createKeywordKey(keyword, matchType) {
  return `${keyword}|||${matchType}`.toLowerCase();
}

// Create sets for quick lookup
// MS_Negatives keywords (all)
const msKeywordSet = new Set();
if (Array.isArray(msItems)) {
  msItems.forEach(item => {
    if (item.keyword && item.match_type) {
      msKeywordSet.add(createKeywordKey(item.keyword, item.match_type));
    }
  });
}

// GA_Negatives keywords (all)
const gaKeywordSet = new Set();
if (Array.isArray(gaItems)) {
  gaItems.forEach(item => {
    if (item.keyword && item.match_type) {
      gaKeywordSet.add(createKeywordKey(item.keyword, item.match_type));
    }
  });
}

// Find keywords to add_to_MS
// Logic: From GA_Negatives (specific list_names only), find KWs NOT in MS_Negatives
const addToMS = [];
if (Array.isArray(gaItems)) {
  gaItems.forEach(item => {
    // Check if this item is from one of the target list names
    if (item.list_name && targetListNames.includes(item.list_name)) {
      if (item.keyword && item.match_type) {
        const key = createKeywordKey(item.keyword, item.match_type);
        // If NOT in MS_Negatives, add to the list
        if (!msKeywordSet.has(key)) {
          addToMS.push({
            keyword: item.keyword,
            match_type: item.match_type,
            list_name: item.list_name
          });
        }
      }
    }
  });
}

// Find keywords to add_to_GA
// Logic: From MS_Negatives, find KWs NOT in GA_Negatives
const addToGA = [];
if (Array.isArray(msItems)) {
  msItems.forEach(item => {
    if (item.keyword && item.match_type) {
      const key = createKeywordKey(item.keyword, item.match_type);
      // If NOT in GA_Negatives, add to the list
      if (!gaKeywordSet.has(key)) {
        addToGA.push({
          keyword: item.keyword,
          match_type: item.match_type,
          list_name: item.list_name || ''
        });
      }
    }
  });
}

// Prepare output for Negatives_Diff sheet
// We need to create rows with two columns: add_to_GA and add_to_MS
const maxRows = Math.max(addToGA.length, addToMS.length);
const outputRows = [];

for (let i = 0; i < maxRows; i++) {
  const row = {
    add_to_GA: '',
    add_to_MS: ''
  };

  if (i < addToGA.length) {
    const item = addToGA[i];
    row.add_to_GA = `${item.keyword} (${item.match_type})`;
  }

  if (i < addToMS.length) {
    const item = addToMS[i];
    row.add_to_MS = `${item.keyword} (${item.match_type})`;
  }

  outputRows.push(row);
}

// Return the data
return outputRows.map(row => ({ json: row }));
